class MagicPotion {
  #potency;

  constructor(potency) {
    this.#potency = potency;
    this.name = "Mysterious Elixir";
  }

  brew() {
    return `A mysterious elixir with potency ${this.#potency}!`;
  }
}

const healingPotion = new MagicPotion(10);
const strengthPotion = new MagicPotion(25);

console.log(healingPotion.brew());
console.log(strengthPotion.brew());

